          do {
            var o = Math.round, r = Math.random, s = 255;
            var col = 'rgba(' + o(r() * s) + ',' + o(r() * s) + ',' + o(r() * s) + ',' + r().toFixed(1) + ')';
          } while (col == 'rgba(255,255,255,255)')
